"""Schema-drift gate for the full MCP tool catalog.

Treats the ~196-tool MCP surface as a de facto public API ahead of a future
1.0. Captures name, inputSchema, output structure, read/write classification,
and required capability (env var) for every registered tool, and fails until
the fixture below is deliberately updated to match an intentional change.

This complements, and deliberately does not duplicate, the existing
`tests/test_*_tools_schema_characterization.py` suite (one file per domain,
already exhaustive at 196/196 tools, each asserting a tool's full
description/parameters/output_schema verbatim). That suite exists to freeze
each domain's own contract in place across refactors (e.g. moving a tool
between files); this one exists to make "the whole catalog is one contract"
an explicit, single, versioned artifact with read/write classification and
capability metadata neither that suite nor anything else in this project
currently captures.

Captured from `release/0.5.0` (196 tools) via a live MCPServer built through
`server.create_app()` under maximally-permissive Settings (every scope
enabled, `attachment_root` set) -- the source of truth this test protects.
Do not "fix" this fixture to match a future change without confirming the
new tool-contract shape is actually intended.

Fixture format per tool:
- `description_hash`: sha256 of the tool's full docstring/description, not
  the text itself. Storing ~196 multi-line docstrings verbatim would make
  every prose wording improvement (typo fix, clarity pass) trip this gate --
  noise that trains reviewers to rubber-stamp updates, defeating its purpose.
  Hashing still catches presence/absence and any edit; the actual current
  text stays independently pinned by the per-domain characterization suite,
  so nothing is lost. On a mismatch, the failure message below prints the
  tool's *current* live description so a reviewer can judge substance vs.
  wording before deciding to update the snapshot.
- `input_schema` / `output_schema`: the full JSON Schema dict, or `None` for
  tools registered with `structured_output=False` (select/write-trimmable
  tools -- see `tools_runtime.register_selected_tools`'s docstring). `None`
  here is correct, real behavior for those tools, not a gap to paper over.
- `annotations`: the MCP tool annotations (readOnlyHint, destructiveHint,
  idempotentHint, openWorldHint) exactly as a client receives them.
- `classification`: `"read"` or `"write"`, derived from `tools.py`'s
  `READ_TOOLS_BY_SCOPE`/`WRITE_TOOLS_BY_SCOPE`/`PERSONAL_MUTATION_TOOLS`/
  `ATTACHMENT_UPLOAD_TOOLS` -- the same partition `test_tool_groups.py`
  already proves is disjoint and exhaustive.
- `scope`: for container uploads, the alternative write scopes joined with `|`;
  otherwise the internal scope key (`"project"`, `"work_package"`, `"admin"`,
  etc.) those same tables use as their join key.
- `capability_env_vars`: every `OPENPROJECT_ENABLE_*`/`OPENPROJECT_ATTACHMENT_ROOT`
  env var that must be set for this tool to be registered at all (a tuple,
  since `PERSONAL_MUTATION_TOOLS` needs both its read and write flag, and
  uploads additionally need a configured attachment root). Container uploads
  list only the root here because no single write flag is required: any one of
  the paired scopes in `scope` suffices, verified by the registration tests.

To regenerate after an intentional tool-contract change: build a live
MCPServer via `server.create_app()` under the same maximally-permissive
Settings as `_all_scopes_enabled_settings()` below, call `await
mcp.list_tools()`, and re-derive each tool's entry using this module's own
`_classify()` helper -- there is no separate script or pytest flag for this
(matching this project's existing convention for `test_model_shapes.py`'s
own fixture: hand-regenerate, then let PR diff review confirm the change is
intended before committing the new fixture values).
"""

from __future__ import annotations

import asyncio
import hashlib
from typing import Any

import pytest

from openproject_ce_mcp import tools
from openproject_ce_mcp.config import READ_SCOPE_ENV_VAR, WRITE_GROUP_REQUIREMENTS, Settings
from openproject_ce_mcp.server import create_app

# Mirrors config.py's own OPENPROJECT_ENABLE_<SCOPE>_WRITE naming convention
# (see Settings.from_env/WRITE_GROUP_REQUIREMENTS) -- no public
# WRITE_SCOPE_ENV_VAR export exists to reuse, unlike READ_SCOPE_ENV_VAR.
_ALL_WRITE_SCOPES = frozenset(tools.WRITE_TOOLS_BY_SCOPE) | {"personal"}
_WRITE_SCOPE_ENV_VAR: dict[str, str] = {
    scope: f"OPENPROJECT_ENABLE_{scope.upper()}_WRITE" for scope in _ALL_WRITE_SCOPES
}

# scope -> its paired read env var, per WRITE_GROUP_REQUIREMENTS -- the same
# real invariant Settings.from_env enforces at startup (a write flag on
# without its matching read flag is a ConfigError). Used below so every
# write-scope tool's capability_env_vars records BOTH, not just the write
# flag: if that from_env enforcement were ever weakened/removed,
# enabled_tool_names() would still register the tool with read disabled
# (it only checks write_enabled(scope) itself), a real capability-gate
# regression this schema-drift gate must be able to catch.
_WRITE_SCOPE_PAIRED_READ_ENV_VAR: dict[str, str] = {
    write_key.removesuffix("_write"): read_env_var for write_key, _, _, read_env_var in WRITE_GROUP_REQUIREMENTS
}


def _classify() -> dict[str, tuple[str, str, tuple[str, ...]]]:
    """tool name -> (classification, scope, capability_env_vars), derived
    from tools.py's classification tables -- the same tables
    test_tool_groups.py already proves partition the full tool set with no
    overlaps or gaps.

    `capability_env_vars` also folds in `tools.ADDITIONAL_READ_SCOPES_BY_TOOL`
    for any tool listed there -- a tool's home scope alone understates its
    real registration requirements for these (e.g.
    `get_project_work_package_context`'s home scope is "project", but
    `enabled_tool_names()` additionally requires work_package AND version
    read). Omitting these env vars here would let a real capability-gate
    change to one of these tools drift unnoticed past this schema-drift gate
    -- exactly what this gate exists to catch."""
    classification: dict[str, tuple[str, str, tuple[str, ...]]] = {}
    for scope, names in tools.READ_TOOLS_BY_SCOPE.items():
        for name in names:
            classification[name] = ("read", scope, (READ_SCOPE_ENV_VAR[scope],))
    for scope, names in tools.WRITE_TOOLS_BY_SCOPE.items():
        for name in names:
            classification[name] = (
                "write",
                scope,
                (_WRITE_SCOPE_ENV_VAR[scope], _WRITE_SCOPE_PAIRED_READ_ENV_VAR[scope]),
            )
    for name in tools.PERSONAL_MUTATION_TOOLS:
        classification[name] = (
            "write",
            "personal",
            (READ_SCOPE_ENV_VAR["personal"], _WRITE_SCOPE_ENV_VAR["personal"]),
        )
    for name in tools.WORK_PACKAGE_UPLOAD_TOOLS:
        classification[name] = (
            "write",
            "work_package",
            (
                _WRITE_SCOPE_ENV_VAR["work_package"],
                _WRITE_SCOPE_PAIRED_READ_ENV_VAR["work_package"],
                "OPENPROJECT_ATTACHMENT_ROOT",
            ),
        )
    for name in tools.CONTAINER_UPLOAD_TOOLS:
        classification[name] = (
            "write",
            "|".join(tools.CONTAINER_UPLOAD_WRITE_SCOPES),
            ("OPENPROJECT_ATTACHMENT_ROOT",),
        )
    for name, additional_scopes in tools.ADDITIONAL_READ_SCOPES_BY_TOOL.items():
        kind, scope, env_vars = classification[name]
        additional_env_vars = tuple(READ_SCOPE_ENV_VAR[s] for s in sorted(additional_scopes))
        classification[name] = (kind, scope, tuple(dict.fromkeys(env_vars + additional_env_vars)))
    return classification


def _all_scopes_enabled_settings() -> Settings:
    return Settings(
        base_url="https://op.example.com",
        api_token="token",
        timeout=12,
        verify_ssl=True,
        default_page_size=20,
        max_page_size=50,
        max_results=100,
        log_level="WARNING",
        read_projects=("*",),
        write_projects=("*",),
        enable_work_package_read=True,
        enable_project_read=True,
        enable_membership_read=True,
        enable_version_read=True,
        enable_board_read=True,
        enable_meeting_read=True,
        enable_personal_read=True,
        enable_admin_read=True,
        enable_user_schedule_read=True,
        enable_work_package_write=True,
        enable_project_write=True,
        enable_membership_write=True,
        enable_version_write=True,
        enable_board_write=True,
        enable_meeting_write=True,
        enable_personal_write=True,
        enable_admin_write=True,
        enable_user_schedule_write=True,
        enable_metadata_tools=True,
        attachment_root="/tmp",
    )


def _live_catalog() -> dict[str, Any]:
    mcp = create_app(_all_scopes_enabled_settings())
    return {t.name: t for t in asyncio.run(mcp.list_tools())}


@pytest.fixture(scope="module")
def live_catalog() -> dict[str, Any]:
    # Built once per test run, not once per parametrized case (196 of them) --
    # constructing a full MCPServer registers every tool with the SDK, which
    # is real work, not free introspection.
    return _live_catalog()


