def test_live_tool_count_matches_the_fixture(live_catalog: dict[str, Any]) -> None:
    assert len(live_catalog) == len(TOOL_CONTRACT_SNAPSHOT), (
        f"live tool count {len(live_catalog)} != fixture tool count {len(TOOL_CONTRACT_SNAPSHOT)} "
        "-- run the regeneration steps in this module's own docstring"
    )


def test_every_registered_tool_is_captured_in_the_fixture(live_catalog: dict[str, Any]) -> None:
    found = set(live_catalog)
    expected = set(TOOL_CONTRACT_SNAPSHOT)
    assert found == expected, (
        f"Registered tools changed since the fixture was captured: added={found - expected} removed={expected - found}"
    )


_CLASSIFICATION = _classify()


@pytest.mark.parametrize("name", sorted(TOOL_CONTRACT_SNAPSHOT))
def test_tool_contract_unchanged(name: str, live_catalog: dict[str, Any]) -> None:
    tool = live_catalog[name]
    expected = TOOL_CONTRACT_SNAPSHOT[name]

    assert tool.input_schema == expected["input_schema"], f"{name}: inputSchema changed"
    assert tool.output_schema == expected["output_schema"], f"{name}: output schema changed"
    annotations = tool.annotations.model_dump(by_alias=True, exclude_none=True) if tool.annotations else None
    assert annotations == expected["annotations"], f"{name}: annotations changed"

    live_hash = hashlib.sha256((tool.description or "").encode()).hexdigest()
    assert live_hash == expected["description_hash"], (
        f"{name}: description changed -- current text:\n{tool.description!r}"
    )

    actual_classification, actual_scope, actual_env_vars = _CLASSIFICATION[name]
    assert actual_classification == expected["classification"], f"{name}: read/write classification changed"
    assert actual_scope == expected["scope"], f"{name}: scope changed"
    assert actual_env_vars == expected["capability_env_vars"], f"{name}: required capability changed"
